ROW.COLUMN:
SELECT 
@MINER@.F_STRUCTURING_AC_RULE_B(@Lrf_Digits,                   
  @Curr_Type,                    
  @All_Trans_Src_Fl,             
  @MINER@.Lst(@Incl_Trans_Src_Lst),	          
  @All_Jurisdictions_Fl,         
  @MINER@.Lst(@Incl_Jurisdictions_Lst),       
  @MINER@.Lst(@Mantas_Bus_Acct_Type_Lst),
  @Look_Back_Period,             
  @MINER@.Lst(@Incl_MI_Trxn_Prdct_Type_Lst),       
  @MINER@.Lst(@Incl_Cash_Trxn_Prdct_Type_Lst),
  @MINER@.Lst(@Incl_Wire_Trxn_Prdct_Type_Lst),                             
  @LE_R1,                        
  @LE_R2,                        
  @UE_R1,                        
  @UE_R2,                        
  @Min_Attempts,
  @MINER@.Lst(@Incld_Acct_Hldr_Typ_Cd) 
) as ACCT_SEQ_ID,
'dummy' as ACCT_INTRL_ID,  -- dataset key to join Sub-rule with pattern
'BENE' as Job_type 
FROM dual

UNION ALL 

SELECT c.ACCT_SEQ_ID, c.ACCT_INTRL_ID, 'BENE' as Job_type 
FROM 
(select * from @MINER@.DSVIEW118864178) c

